"""Generate the exact Prompt 9 handoff and C++ cue catalog; never generate audio."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
prompt = (ROOT / 'docs/mvp-implementation-prompts.md').read_text(encoding='utf-8')
families = []
for line in prompt.splitlines():
    if not line.startswith('| `') or ' | ' not in line:
        continue
    cells = [x.strip() for x in line.strip('|').split('|')]
    name = cells[0].strip('`')
    if not name.startswith(('amb_', 'pip_', 'ui_', 'reward_', 'shop_', 'pot_', 'channel_', 'ball_', 'toy_', 'basket_', 'cushion_', 'switch_', 'gate_', 'furnishing_', 'bowl_')):
        continue
    if len(cells) != 4 or ';' not in cells[2]:
        continue
    count = int(cells[2].rsplit(';', 1)[1].strip())
    families.append(dict(id=name, provider='ElevenLabs', prompt=cells[1], target=cells[2], event=cells[3], variants=count))
for name, title in [('music_garden_afternoon', 'Garden afternoon'), ('music_garden_puzzles', 'Little garden puzzles'), ('music_pip_at_home', 'Pip feels at home')]:
    section = prompt.split('### '+title+'\n', 1)[1].split('\n### ', 1)[0].split('\n## ', 1)[0]
    families.append(dict(id=name, provider='Suno', prompt=section.strip(), target='6–10 s' if name.endswith('home') else '60–90 s loop', event=title, variants=1))
assert len(families) == 32
manifest_path = ROOT / 'assets/runtime/audio/catalog.json'
existing = json.loads(manifest_path.read_text()) if manifest_path.exists() else {'clips': []}
old = {x['id']: x for x in existing['clips']}
clips, header = [], ['// Generated by scripts/prepare-audio-catalog.py.\n#pragma once\n#include <array>\n#include <string_view>\nnamespace paws {\nstruct AudioClipSpec { std::string_view id, family; int bus; bool loop; float gain; double cooldown; };\ninline constexpr std::array<AudioClipSpec,47> audioClips{{']
checklist = ['# Prompt 9 audio production checklist', '', 'No audio is generated by this script. All 47 deliveries require real source files and review.', '', 'Use ElevenLabs Sound Effects for the 44 effects/ambience clips and Suno Custom / Instrumental with empty lyrics for music. Retain the best original download without renaming away its format. Do not substitute another music provider.', '', 'Per clip: retain source ID/link, exact prompt/settings/date and account use-rights evidence in `artifacts/audio-production/sources/`. Edit a copy, audition, trim/clean and export PCM16 WAV. Short dry effects should be mono; music/air can be stereo. Keep peak <= -2 dBFS, no clipping, and at most 24 MiB decoded at the browser device sample rate (usually 48 kHz). Budget retained PCM at 48 MiB; the backend may duplicate active buffers. Prefer mono music if a 90-second stereo track exceeds the budget.', '', 'Loops must be pre-trimmed to the full WAV buffer: the pinned backend loops the entire buffer, with no subrange or sample-accurate crossfade. Audition five repeats in-game and retain sample boundaries, waveform and seam review. Do not set accepted/listening fields before those checks. Music transitions use a short fade-out, release, then fade-in without overlapping decoded tracks.', '', 'Place edited WAVs under `artifacts/audio-production/edited/`, record metadata using the template below, and run `python scripts/import-audio.py <metadata.json>`. Originals stay outside the deployed tree. Runtime destinations follow. Missing files remain absent, with no silent placeholders.', '']
for f in families:
    bus = 0 if f['id'].startswith('music_') else 1 if f['id'].startswith('amb_') else 2
    loop = f['id'] in ('amb_garden_air','pip_purr','ball_roll','music_garden_afternoon','music_garden_puzzles')
    gain = .18 if bus == 0 else .2 if bus == 1 else .35
    if f['id'] in ('pip_paws_stone','ui_select','ui_panel'): gain = .13
    cooldown = 2 if f['id'].startswith('pip_') and f['id'] != 'pip_paws_stone' else .12
    checklist += ['## '+f['id'], '', f"Provider: {f['provider']}. Target: {f['target']}. Event: {f['event']}.", '', f['prompt'], '']
    for v in range(1, f['variants']+1):
        name = f"{f['id']}_{v:02}"
        clip = dict(id=name, family=f['id'], provider=f['provider'], prompt=f['prompt'], target=f['target'], event=f['event'], file=f'{name}.wav', loop=loop, accepted=False, source=None, review=None)
        clip.update(old.get(name, {}))
        clips.append(clip)
        header.append(f'    {{"{name}","{f["id"]}",{bus},{str(loop).lower()},{gain}f,{cooldown}}},')
        checklist.append(f'- `{name}` → `assets/runtime/audio/{name}.wav` (deployed as `assets/audio/{name}.wav`)')
    checklist.append('')
assert len(clips) == 47
manifest_path.parent.mkdir(parents=True, exist_ok=True)
manifest_path.write_text(json.dumps(dict(schema=1, contentId='paws-audio-1', clips=clips), indent=2, ensure_ascii=False)+'\n', encoding='utf-8')
(ROOT/'src/audio_catalog.hpp').write_text('\n'.join(header)+'\n}};\n}\n', encoding='utf-8')
(ROOT/'docs/phase9-audio-production.md').write_text('\n'.join(checklist).replace('using the template below', 'using [the import template](../artifacts/audio-production/import-template.json)'), encoding='utf-8')
print('Prepared 32 families / 47 clips; preserved existing import metadata.')
